//! Core iterator contract.
//! `std.collections.Iterator` defines the portable state-passing shape used by
//! collection traversal.

module std.collections.Iterator.

/// Iterator represents a traversal state for values of type `T`.
/// Input: type parameter `T`.
/// Output: an opaque traversal-state type.
/// Transformation: hides the selected backend representation behind the
/// portable `std.collections.Iterator` API.

pub opaque type Iterator[T].

/// Step represents one yielded value and the next iterator state.
/// Input: type parameter `T`.
/// Output: a structural pair of the yielded value and next iterator state.
/// Transformation: makes traversal state explicit and immutable at the source
/// level.

pub type Step[T] =
    {value: T, next: Iterator[T]}.

/// Applies a callback to each value yielded by an iterator.
/// Input: one iterator state and one callback from `T` to `Unit`.
/// Output: `Unit`.
/// Transformation: repeatedly calls `next(iterator)`. When traversal is
/// exhausted, returns `Unit`. When a value is yielded, calls `cb(value)` for
/// its effect and continues with the returned next iterator state.
/// ```terlan
/// module iterator_each_example.
/// import std.collections.Iterator.{Iterator, Step}.
/// import std.core.Option.{None, Option, Some}.
/// import std.core.Unit.{Unit}.
/// pub each(iterator: Iterator[T], cb: (T) -> Unit): Unit ->
///    case next(iterator) {
///        None ->
///            Unit;
///        Some({value: value, next: rest}) ->
///            let _done = cb(value);
///            each(rest, cb)
///    }.
/// ```

pub each(iterator: Iterator[T], cb: (T) -> Unit): Unit.

/// Returns the next value and iterator state, or `None` when exhausted.
/// Input: one iterator state.
/// Output: `Some({value: value, next: next})` for the next item, or `None` when traversal
/// is complete.
/// Transformation: lowers through the compiler-owned `core.iterator.next`
/// intrinsic and advances traversal by returning a new iterator state rather
/// than mutating the current value.

@pure
pub next(iterator: Iterator[T]): std.core.Option[Step[T]].

//! Core list collection contract.
//! `std.collections.List` is the portable ordered collection surface for Terlan list
//! values.

module std.collections.List.

/// List represents an ordered collection of values.
/// Input: type parameter `T`.
/// Output: an opaque ordered collection type.
/// Transformation: hides the selected backend representation behind the
/// portable `std.collections.List` API.

pub opaque type List[T].

/// Removes every value from a list.
/// Input: a mutable `List[T]` receiver.
/// Output: `Unit`.
/// Transformation: lowers through the compiler-owned `core.list.clear`
/// intrinsic and updates the receiver binding so it becomes empty.

@pure
pub (mut list: List[T]) clear(): Unit.

/// Concatenates two lists in source order.
/// Input: a `List[T]` receiver and a second `List[T]`.
/// Output: a new list containing the receiver values followed by the second
/// list values.
/// Transformation: lowers through the compiler-owned `core.list.concat`
/// intrinsic and leaves both input lists unchanged.

@pure
pub (list: List[T]) concat(other: List[T]): List[T].

/// Applies a callback to each value in a list.
/// Input: one `List[T]` receiver and one callback from `T` to `Unit`.
/// Output: `Unit`.
/// Transformation: creates a traversal state with `list.iterator()` and
/// delegates to `std.collections.Iterator.each`, preserving list contents while the
/// callback performs any requested effects.

@pure
pub (list: List[T]) each(cb: (T) -> Unit): Unit.

/// Returns the first value in a list.
/// Input: one `List[T]`.
/// Output: `Some(value)` when the list is non-empty;
/// otherwise `None`.
/// Transformation: lowers through the compiler-owned `core.list.first`
/// intrinsic and observes the receiver without changing its contents.

@pure
pub (list: List[T]) first(): std.core.Option[T].

/// Maps each value to a list and concatenates those lists in source order.
/// This ordinary Terlan implementation is also the semantic target for list
/// comprehension desugaring; no backend-specific comprehension runtime exists.

pub flat_map[A, B](values: List[A], callback: (A) -> List[B]): List[B].

/// Returns whether a list contains no values.
/// Input: one `List[T]`.
/// Output: `true` when the list is empty;
/// otherwise `false`.
/// Transformation: lowers through the compiler-owned `core.list.is_empty`
/// intrinsic and observes the receiver without changing its contents.

@pure
pub (list: List[T]) is_empty(): Bool.

/// Returns an iterator over the list.
/// Input: one `List[T]`.
/// Output: a `std.collections.Iterator[T]` positioned at the beginning
/// of the list.
/// Transformation: lowers through the compiler-owned `core.list.iterator`
/// intrinsic. The source-level iterator state is immutable;
/// backends choose
/// the efficient representation behind the opaque iterator type.

@pure
pub (list: List[T]) iterator(): std.collections.Iterator[T].

/// Returns the number of values in a list.
/// Input: one `List[T]`.
/// Output: the number of values currently visible in the list.
/// Transformation: lowers through the compiler-owned `core.list.length`
/// intrinsic and observes the receiver without changing its contents.

@pure
pub (list: List[T]) length(): Int.

/// Creates an empty list.
/// Input: no value input.
/// Output: an empty `List[T]`.
/// Transformation: lowers through the compiler-owned `core.list.new`
/// intrinsic, using the selected backend's canonical empty-list value.

@pure
pub new[T](): List[T].

/// Appends a value to the end of a list.
/// Input: a mutable `List[T]` receiver and one value of type `T`.
/// Output: `Unit`.
/// Transformation: lowers through the compiler-owned `core.list.push`
/// intrinsic and updates the receiver binding in source order. Pipe chains
/// continue with the updated receiver.

@pure
pub (mut list: List[T]) push(value: T): Unit.

/// Returns every value after the first.
/// Input: one `List[T]`.
/// Output: `Some(rest)` for a non-empty list, including `Some([])` for a
/// singleton list;
/// otherwise `None`.
/// Transformation: lowers through the compiler-owned `core.list.rest`
/// intrinsic without changing the receiver.

@pure
pub (list: List[T]) rest(): std.core.Option[List[T]].

/// Removes the first matching occurrence for each supplied value.
/// Input: a `List[T]` receiver and a list of values to remove.
/// Output: a new list with one matching occurrence removed in removal-list
/// order for each supplied value.
/// Transformation: lowers through the compiler-owned `core.list.subtract`
/// intrinsic, uses structural value equality, and leaves both inputs unchanged.

@pure
pub (list: List[T]) subtract(values: List[T]): List[T].

/// Constructs a list from positional values.
/// Input: zero or more values of the same element type `T`.
/// Output: a `List[T]` containing the supplied values in source order.
/// Transformation: uses constructor varargs to pack positional values into the
/// portable list representation.

pub constructor List[T] {
    (...items: T): List[T] ->
        items
}.

//! Core map collection contract.
//! `std.collections.Map` is the portable key-value collection surface. Backends own
//! the efficient runtime representation while preserving this source contract.

module std.collections.Map.

/// Map represents a collection of values addressed by keys.
/// Input: type parameters `K` and `V`.
/// Output: an opaque key-value collection type.
/// Transformation: hides the selected backend representation behind the
/// portable `std.collections.Map` API.

pub opaque type Map[K, V].

/// Removes every entry from a map.
/// Input: a mutable `Map[K, V]` receiver.
/// Output: `Unit`.
/// Transformation: lowers through the compiler-owned `core.map.clear`
/// intrinsic and updates the receiver binding so it becomes empty.

@pure
pub (mut map: Map[K, V]) clear(): Unit.

/// Returns whether a key exists.
/// Input: one `Map[K, V]` receiver and one key of type `K`.
/// Output: `true` when the key exists;
/// otherwise `false`.
/// Transformation: lowers through the compiler-owned `core.map.contains_key`
/// intrinsic and observes the receiver without changing its contents.

@pure
pub (map: Map[K, V]) contains_key(key: K): Bool.

/// Creates a map from explicit key-value entry tuples.
/// Input: one `List[{K, V}]`.
/// Output: a `Map[K, V]` containing the supplied entries.
/// Transformation: lowers through the compiler-owned `core.map.from_entries`
/// intrinsic. Backends choose the efficient map representation and duplicate
/// key handling behind the portable `Map[K, V]` contract.

@pure
pub from_entries[K, V](entries: List[{K, V}]): Map[K, V].

/// Looks up a value by key.
/// Input: one `Map[K, V]` receiver and one key of type `K`.
/// Output: `Some(value)` when the key exists;
/// otherwise `None`.
/// Transformation: lowers through the compiler-owned `core.map.get`
/// intrinsic and observes the receiver without changing its contents.

@pure
pub (map: Map[K, V]) get(key: K): std.core.Option[V].

/// Returns whether a map contains no entries.
/// Input: one `Map[K, V]`.
/// Output: `true` when the map has no entries;
/// otherwise `false`.
/// Transformation: lowers through the compiler-owned `core.map.is_empty`
/// intrinsic and observes the receiver without changing its contents.

@pure
pub (map: Map[K, V]) is_empty(): Bool.

/// Creates an iterator over key-value entries.
/// Input: one `Map[K, V]`.
/// Output: an `Iterator[{K, V}]` yielding one `{key, value}` pair per entry.
/// Transformation: lowers through the compiler-owned `core.map.iterator`
/// intrinsic. Backends choose their own traversal order and representation while
/// preserving the portable pair-yielding contract.

@pure
pub (map: Map[K, V]) iterator(): std.collections.Iterator[{K, V}].

/// Creates an empty map.
/// Input: no value input.
/// Output: an empty `Map[K, V]`.
/// Transformation: lowers through the compiler-owned `core.map.new`
/// intrinsic, using the selected backend's canonical empty-map value.

@pure
pub new[K, V](): Map[K, V].

/// Inserts or replaces a key-value entry.
/// Input: a mutable `Map[K, V]` receiver, one key, and one value.
/// Output: `Unit`.
/// Transformation: lowers through the compiler-owned `core.map.put`
/// intrinsic and updates the receiver binding in source order. Pipe chains
/// continue with the updated receiver.

@pure
pub (mut map: Map[K, V]) put(key: K, value: V): Unit.

/// Removes a key-value entry if it exists.
/// Input: a mutable `Map[K, V]` receiver and one key.
/// Output: `Unit`.
/// Transformation: lowers through the compiler-owned `core.map.remove`
/// intrinsic and updates the receiver binding in source order.

@pure
pub (mut map: Map[K, V]) remove(key: K): Unit.

/// Returns the number of entries in a map.
/// Input: one `Map[K, V]`.
/// Output: the number of key-value entries currently visible in the map.
/// Transformation: lowers through the compiler-owned `core.map.size`
/// intrinsic and observes the receiver without changing its contents.

@pure
pub (map: Map[K, V]) size(): Int.

/// Returns a value and a map without the requested key.
/// Input: one `Map[K, V]` and one key of type `K`.
/// Output: `{Some(value), remaining}` when the key exists, otherwise
/// `{None, original}`.
/// Transformation: observes the value before removing the key from a local
/// persistent map value. The input map remains available to the caller.

@pure
pub take[K, V](map: Map[K, V], key: K): {std.core.Option[V], Map[K, V]}.

/// Constructs a map from explicit key-value entry tuples.
/// Input: zero or more `{K, V}` entries.
/// Output: a `Map[K, V]` containing the supplied entries.
/// Transformation: uses constructor varargs to pack positional entries into a
/// portable list and delegates to `from_entries` so backend-specific map
/// representation stays behind the intrinsic boundary. Later duplicate keys
/// replace earlier keys according to the backend map contract.

pub constructor Map[K, V] {
    (...entries: {K, V}): Map[K, V] ->
        from_entries(entries)
}.

//! Core addition trait.
//! `std.core.Add` defines the type-directed contract behind source `+` for
//! values whose addition or concatenation is safe and predictable.

module std.core.Add.

/// Describes values that can be combined with `+`.
/// Input: a left value of type `Left` and right value of type `Right`.
/// Output: a result value of type `Result`.
/// Transformation: combines two values without mutating either input. Primitive
/// implementations map to target-native numeric addition or string
/// concatenation.

pub trait Add[Left, Right, Result] {
    add(left: Left, right: Right): Result.
}.

pub impl Add[Float, Float, Float] for Float {
}.

pub impl Add[Int, Int, Int] for Int {
}.

pub impl Add[String, String, String] for String {
}.

//! Core symbolic atom helpers.
//! `std.core.Atom` documents and supports Terlan's language-neutral singleton
//! symbol primitive. Source code should define named aliases with
//! `Atom["name"]` and use those aliases in expressions and patterns.
//! Public singleton aliases have one declaration in a compilation graph.
//! Import the existing alias instead of declaring the same atom in another module.
//! The compiler reports `duplicate_atom_alias` for duplicate public declarations.
//! Private aliases, opaque types, unions, and references to shared aliases remain valid.
//! Atom names are finite source-level symbols. Runtime text must not create
//! new atoms. Dynamic input should remain `String` or be matched through an
//! explicit finite table that returns `Result` for unknown values.

module std.core.Atom.

/// Automatic policy marker shared across APIs.

pub type Auto =
    Atom["auto"].

/// Left direction marker shared across APIs.

pub type Left =
    Atom["left"].

/// Manual policy marker shared across APIs.

pub type Manual =
    Atom["manual"].

/// Strict policy marker shared across APIs.

pub type Strict =
    Atom["strict"].

/// Returns whether two singleton atom-backed values are equal.
/// Input: two values of the same singleton atom-backed type `T`.
/// Output: `true` when both values are the same symbolic value; otherwise
/// `false`.
/// Transformation: delegates to Terlan equality without exposing backend atom
/// syntax or target-specific representation details.
/// ```terlan
/// module atom_equal_example.
/// pub type Ready = Atom["ready"].
/// pub demo(): Bool ->
///    std.core.Atom.equal(Ready, Ready).
/// ```

@pure
pub equal[T](left: T, right: T): Bool.

/// Renders a singleton atom-backed value as canonical text.
/// Input: one language-neutral atom value, including values introduced through
/// `Atom["name"]` aliases.
/// Output: the canonical `String` payload for that atom.
/// Transformation: lowers through the compiler-owned `core.atom.to_string`
/// intrinsic so source code does not depend on a backend atom representation.
/// ```terlan
/// module atom_to_string_example.
/// pub type Ready = Atom["ready"].
/// pub demo(): String ->
///    std.core.Atom.to_string(Ready).
/// ```

@pure
pub to_string(value: Atom): String.

//! Core boolean conformance helpers.
//! `std.core.Bool` provides named operations used by stdlib trait/conformance
//! implementations for `Bool`.

module std.core.Bool.

/// Compares two `Bool` values using the canonical total ordering.
/// Input: two `Bool` values.
/// Output: `Lt` when `left` is `false` and `right` is `true`, `Eq` when
/// both inputs are equal, and `Gt` when `left` is `true` and `right` is
/// `false`.
/// Transformation: maps the closed boolean domain onto
/// `std.core.Ordering.Comparison` with `false < true`.
/// This is an ordinary Terlan implementation. Calls use this body rather than
/// a compiler-owned comparison implementation.
/// ```terlan
/// module bool_compare_example.
/// pub demo(): std.core.Ordering.Comparison ->
///    std.core.Bool.compare(false, true).
/// ```

@pure
pub compare(left: Bool, right: Bool): std.core.Ordering.Comparison.

/// Returns whether two `Bool` values are equal.
/// Input: two `Bool` values.
/// Output: `true` when both inputs have the same truth value; otherwise
/// `false`.
/// Transformation: delegates to exact Terlan equality for the two boolean
/// values.
/// This function exists as a named implementation hook for future
/// `Comparable[Bool]` / equality-style trait conformance. Ordinary Terlan code
/// may use the `==` operator directly.
/// ```terlan
/// module bool_equal_example.
/// pub equal(Left: Bool, Right: Bool): Bool ->
///    Left == Right.
/// pub demo(Value: Bool): Bool ->
///    equal(Value, Value).
/// ```

@pure
pub equal(Left: Bool, Right: Bool): Bool.

/// Parses a canonical UTF-8 `String` into a `Bool`.
/// Input: one `String` value.
/// Output: `Option[Bool]`, where `"true"` returns `Some(true)`, `"false"`
/// returns `Some(false)`, and any other string returns `None`.
/// Transformation: recognizes only the canonical spellings used by
/// `std.core.String.Parse[Bool]` and rejects all other strings.
/// ```terlan
/// module bool_from_string_example.
/// pub demo(): Option[Bool] ->
///    std.core.Bool.from_string("true").
/// ```

pub from_string(value: String): Option[Bool].

/// Returns whether a `Bool` value is false.
/// Input: one `Bool` value.
/// Output: `true` when the input is `false`; otherwise `false`.
/// Transformation: compares the input against the canonical `false` value.
/// ```terlan
/// module bool_is_false_example.
/// pub demo(value: Bool): Bool ->
///     std.core.Bool.is_false(value).
/// ```

@pure
pub is_false(value: Bool): Bool.

/// Returns whether a `Bool` value is true.
/// Input: one `Bool` value.
/// Output: `true` when the input is `true`; otherwise `false`.
/// Transformation: returns the input unchanged under a predicate-style helper
/// name that can be imported or passed around without using operator syntax.
/// ```terlan
/// module bool_is_true_example.
/// pub demo(value: Bool): Bool ->
///     std.core.Bool.is_true(value).
/// ```

@pure
pub is_true(value: Bool): Bool.

/// Renders a `Bool` as its canonical UTF-8 `String`.
/// Input: one `Bool` value.
/// Output: `"true"` for `true` and `"false"` for `false`.
/// Transformation: maps the closed boolean runtime domain onto the canonical
/// string spellings required by `std.core.String.Show[Bool]`.
/// ```terlan
/// module bool_to_string_example.
/// pub demo(): String ->
///    std.core.Bool.to_string(true).
/// ```

@pure
pub to_string(value: Bool): String.

//! Core effect description type.
//! `std.core.Effect` represents an effect description that can be composed as a
//! value. Execution is designed to cross an explicit VM-owned boundary.
//! AOT execution supports concrete native plans built with `succeed`, `map`,
//! `flat_map`, `fail`, and `cancelled`, and checked direct `Mapped` and `FlatMap`
//! constructors. Callbacks execute on the owning VM actor and can suspend;
//! constructing a description does not invoke them.
//! Callbacks must have concrete checked signatures. Incorrect callback arity,
//! non-callable values, and non-Effect flat-map results fail native admission.
//! Failure payloads must be materializable VM values;
//! executable functions and opaque resource handles are not supported as errors.
//! These limits are not general Dynamic execution support.

module std.core.Effect.

/// Cancelled records cooperative cancellation for VM-owned scheduling.

pub type Cancelled =
    {Atom["cancelled"], marker: Unit}.

/// Effect represents a composable effect description.
/// Input: type parameter for the eventual value.
/// Output: an effect descriptor that can be mapped or sequenced.
/// Transformation: keeps effect composition explicit without requiring ordinary
/// Terlan code to use monadic style.

pub type Effect[T] =
    Pure[T]
  | Mapped
  | FlatMap
  | Failed
  | Cancelled.

/// Failed records a typed VM-boundary failure without throwing in source.

pub type Failed =
    {Atom["failed"], error: Dynamic}.

/// FlatMap records an effect-producing continuation without invoking it.

pub type FlatMap =
    {Atom["flat_map"], effect: Dynamic, next: Dynamic}.

/// Mapped records a mapper without invoking it.
/// The descriptor deliberately erases its internal input type at the runtime
/// boundary. The public `Effect[T]` result retains the eventual output type.

pub type Mapped =
    {Atom["mapped"], effect: Dynamic, mapper: Dynamic}.

/// Pure represents a completed effect description.
/// Input: one contained value.
/// Output: a tagged effect descriptor.
/// Transformation: records a value in the effect context without performing
/// runtime work.

pub type Pure[T] =
    {Atom["pure"], value: T}.

/// Creates a cooperatively cancelled effect description.

@pure
pub cancelled(): Effect[T].

/// Creates an inert typed failure description.
/// At `run`, a supported failure terminates the owning actor and preserves its
/// value for VM exit propagation. Payloads must be materializable VM values;
/// executable functions and opaque resource handles are not supported as errors.

@pure
pub fail(error: E): Effect[T].

/// Chains an effect into another effect-producing computation.
/// Input: effect descriptor and continuation.
/// Output: flattened effect descriptor.
/// Transformation: records the continuation without invoking it. The
/// continuation and its returned description execute only at `Effect.run`.

@pure
pub flat_map(effect: Effect[A], next: (A) -> Effect[B]): Effect[B].

/// Maps the eventual value inside an effect description.
/// Input: effect descriptor and pure mapper function.
/// Output: mapped effect descriptor.
/// Transformation: records the mapper without invoking it. The mapper executes
/// only when the resulting description crosses `Effect.run`.

@pure
pub map(effect: Effect[A], mapper: (A) -> B): Effect[B].

/// Declares the VM-owned execution boundary for an effect description.
/// Input: one effect descriptor.
/// Output: the eventual value after executing a supported concrete native plan.
/// Callbacks run on the owning VM actor and may suspend. Failure and cancellation
/// terminate that actor without running later callbacks. This boundary is
/// effectful, unlike inert description construction.
/// Typed combinators and checked direct constructors are supported; arbitrary
/// Dynamic execution is not. Failure payloads must be materializable VM values,
/// not executable functions or opaque resource handles.

pub run(effect: Effect[T]): T.

/// Lifts a plain value into an effect description.
/// Input: one value.
/// Output: completed effect descriptor.
/// Transformation: wraps the value without executing runtime work.

@pure
pub succeed(value: T): Effect[T].

//! Core equality trait.
//! `std.core.Equal` defines explicit, type-directed equality for values whose
//! equality can be represented safely and portably.

module std.core.Equal.

/// Describes values that can be compared for equality.
/// Input: two values of the same type `T`.
/// Output: `true` when the values are equal; otherwise `false`.
/// Transformation: compares two values without changing either input. Primitive
/// implementations delegate to Terlan's exact equality operator, while
/// user-defined implementations may choose a domain-specific equality contract.
/// ```terlan
/// module equal_trait_example.
/// pub trait Equal[T] {
///    equal(left: T, right: T): Bool.
/// }.
/// ```

pub trait Equal[T] {
    equal(left: T, right: T): Bool.
}.

pub impl Equal[Bool] for Bool {
}.

pub impl Equal[Float] for Float {
}.

pub impl Equal[Int] for Int {
}.

pub impl Equal[String] for String {
}.

pub impl Equal[std.core.Ordering.Comparison] for std.core.Ordering.Comparison {
}.

pub impl Equal[std.core.Unit] for std.core.Unit {
}.

//! Core typed error value.
//! `std.core.Error` is the portable base error shape used by standard-library
//! APIs that return typed recoverable failures. Domain errors derive from this
//! struct and add context fields while preserving the common `code` and
//! `message` fields.

module std.core.Error.

/// Error is the common portable error data shape.
/// Input: no runtime input; fields are supplied by constructors.
/// Output: a typed struct containing a stable machine-readable `code` and a
/// human-readable `message`.
/// Transformation: provides a target-neutral data contract that backend-specific
/// failures can map into at module boundaries.

pub struct Error {
    code: Atom,
    message: String
}.

/// Creates an `Error`.
/// Input: one symbolic error code and one human-readable message.
/// Output: an `Error` value with both fields populated.
/// Transformation: constructs the public base error struct without relying on a
/// target-specific exception or atom representation.
/// ```terlan
/// module error_new_example.
/// import std.core.Error.{new}.
/// pub type Invalid = Atom["invalid"].
/// pub demo(): Error ->
///    new(Invalid, "invalid input").
/// ```

pub new(code: Atom, message: String): Error.

/// Converts an error to display text.
/// Input: one `Error` receiver.
/// Output: the receiver's human-readable message.
/// Transformation: reads the message field for generic display paths.

@pure
pub (error: Error) to_string(): String.

//! Core float conformance helpers.
//! `std.core.Float` provides named operations used by stdlib trait/conformance
//! implementations for primitive `Float`.

module std.core.Float.

/// Returns the absolute value of a finite `Float`.
/// Input: one supported finite `Float` value.
/// Output: the non-negative magnitude of the input.
/// Transformation: returns the input unchanged when it is non-negative;
/// otherwise subtracts it from zero.
/// ```terlan
/// module float_abs_example.
/// pub demo(): Float ->
///     std.core.Float.abs(-2.25).
/// ```

@pure
pub abs(value: Float): Float.

/// Returns the least whole Float not less than the input.
/// Input: one finite `Float` value.
/// Output: the mathematical ceiling represented as a `Float`.
/// Transformation: delegates deterministic finite rounding to the VM-owned
/// primitive intrinsic.

@pure
pub ceil(value: Float): Float.

/// Compares two supported finite `Float` values using numeric ordering.
/// Input: two supported finite `Float` values.
/// Output: `Lt` when `left` is numerically less than `right`, `Eq` when the
/// values are equal, and `Gt` when `left` is numerically greater than
/// `right`.
/// Transformation: maps the selected finite float ordering relation onto
/// `std.core.Ordering.Comparison`.
/// This function is the named implementation hook for compiler-known
/// `std.core.Ordering[Float]` conformance in 0.0.1. Non-finite values
/// are outside the 0.0.1 source contract.
/// ```terlan
/// module float_compare_example.
/// pub demo(): std.core.Ordering.Comparison ->
///    std.core.Float.compare(1.5, 2.5).
/// ```

@pure
pub compare(left: Float, right: Float): std.core.Ordering.Comparison.

/// Returns whether two finite `Float` values are equal.
/// Input: two supported finite `Float` values.
/// Output: `true` when both inputs represent the same finite floating-point
/// value; otherwise `false`.
/// Transformation: delegates to exact Terlan equality for the finite float
/// domain selected by the source contract without changing either input.
/// ```terlan
/// module float_equal_example.
/// pub demo(): Bool ->
///     std.core.Float.equal(1.5, 1.5).
/// ```

@pure
pub equal(left: Float, right: Float): Bool.

/// Returns the greatest whole Float not greater than the input.
/// Input: one finite `Float` value.
/// Output: the mathematical floor represented as a `Float`.
/// Transformation: delegates deterministic finite rounding to the VM-owned
/// primitive intrinsic.

@pure
pub floor(value: Float): Float.

/// Parses a canonical UTF-8 `String` into `Float`.
/// Input: one `String` value.
/// Output: `Option[Float]`, where supported finite decimal float text returns
/// `Some(value)` and invalid text returns `None`.
/// Transformation: lowers through the compiler-owned `core.float.from_string`
/// intrinsic and accepts only inputs where the full string is consumed.
/// ```terlan
/// module float_from_string_example.
