//! Core functional abstraction traits.
//! `std.core.Functional` defines higher-kinded traits for container-like
//! computations. These traits are intentionally small: they describe the
//! portable function shapes that targets must preserve without imposing a
//! specific runtime representation.

module std.core.Functional.

/// Applicative describes functors that can lift values and apply lifted
/// functions.
/// Input: a unary type constructor `F[_]`.
/// Output: a trait requiring `pure` and `apply`, while inheriting `Functor`.
/// Transformation: lifts plain values into `F` and applies functions already
/// inside `F` to values inside `F`.

pub trait Applicative[F[_]] extends Functor[F] {
    apply[A, B](f: F[(A) -> B], value: F[A]): F[B].
    pure[A](value: A): F[A].
}.

/// Functor describes values that can map over one contained type parameter.
/// Input: a unary type constructor `F[_]`.
/// Output: a trait requiring `map`.
/// Transformation: maps `F[A]` to `F[B]` by applying a pure function to each
/// present value according to the concrete implementation.

pub trait Functor[F[_]] {
    map[A, B](value: F[A], f: (A) -> B): F[B].
}.

/// Monad describes applicatives that can sequence dependent computations.
/// Input: a unary type constructor `F[_]`.
/// Output: a trait requiring `flat_map`, while inheriting `Applicative`.
/// Transformation: feeds a contained value into a function that returns the
/// same context constructor.

pub trait Monad[F[_]] extends Applicative[F] {
    flat_map[A, B](value: F[A], f: (A) -> F[B]): F[B].
}.

/// ResultFunctor describes success/error containers with two type parameters.
/// Input: a binary type constructor `F[_, _]`.
/// Output: a trait requiring success and error mapping.
/// Transformation: maps either side of a result-like value while preserving the
/// other side. This is the current Terlan form for binary constructors until
/// type lambdas can express `Result[E, _]` as a unary `Monad`.

pub trait ResultFunctor[F[_, _]] {
    map[A, B, E](value: F[A, E], f: (A) -> B): F[B, E].
    map_error[A, E, G](value: F[A, E], f: (E) -> G): F[A, G].
}.

/// ResultMonad describes sequencing for success/error containers.
/// Input: a binary type constructor `F[_, _]`.
/// Output: a trait requiring success-value sequencing with a fixed error type.
/// Transformation: chains successful values into the next result-like
/// computation while preserving errors unchanged.

pub trait ResultMonad[F[_, _]] extends ResultFunctor[F] {
    flat_map[A, B, E](value: F[A, E], f: (A) -> F[B, E]): F[B, E].
}.

pub impl Applicative[std.collections.List] for std.collections.List {
}.

pub impl Applicative[std.core.Option] for std.core.Option {
}.

pub impl Functor[std.collections.List] for std.collections.List {
}.

pub impl Functor[std.core.Option] for std.core.Option {
}.

pub impl Monad[std.collections.List] for std.collections.List {
}.

pub impl Monad[std.core.Option] for std.core.Option {
}.

pub impl ResultFunctor[std.core.Result] for std.core.Result {
}.

pub impl ResultMonad[std.core.Result] for std.core.Result {
}.

//! Core comprehension guard-result contract value.
//! `std.core.GuardResult` defines the opt-in contract used by effectful
//! comprehension filters. `Bool` and `Pure` remain built-in completed results;
//! every deferred result declares the unary container that lifts the complete
//! comprehension.

module std.core.GuardResult.

/// GuardResult represents a completed pure guard decision.
/// Input: none beyond the boolean carried by `Pure`.
/// Output: source-facing guard-result contract value.
/// Transformation: keeps the current 0.0.7 surface pure while reserving the
/// same module for later effectful guard-result adapters.

pub type Completed =
    Pure.

/// Pure represents a completed guard decision.
/// Input: one boolean guard decision.
/// Output: a tagged guard-result descriptor.
/// Transformation: records whether a comprehension candidate should be kept
/// without scheduling runtime work.

pub type Pure =
    {Atom["guard_result"], value: Bool}.

/// Creates an accepting guard result.
/// Input: none.
/// Output: completed guard-result descriptor whose value is `true`.
/// Transformation: records that the current comprehension candidate should be
/// kept.

@pure
pub accept(): Completed.

/// Combines two completed guard results with boolean conjunction.
/// Input: two completed guard-result descriptors.
/// Output: completed descriptor that accepts only when both inputs accept.
/// Transformation: preserves ordinary comprehension filter ordering for pure
/// guard decisions.

@pure
pub both(left: Completed, right: Completed): Completed.

/// Combines two completed guard results with boolean disjunction.
/// Input: two completed guard-result descriptors.
/// Output: completed descriptor that accepts when either input accepts.
/// Transformation: preserves ordinary boolean guard composition inside the
/// guard-result contract.

@pure
pub either(left: Completed, right: Completed): Completed.

/// Converts a boolean into a guard-result value.
/// Input: one boolean guard decision.
/// Output: completed guard-result descriptor.
/// Transformation: wraps the decision without changing its truth value.

@pure
pub from_bool(value: Bool): Completed.

/// Creates a rejecting guard result.
/// Input: none.
/// Output: completed guard-result descriptor whose value is `false`.
/// Transformation: records that the current comprehension candidate should be
/// filtered out.

@pure
pub reject(): Completed.

/// Reads the boolean decision from a completed guard result.
/// Input: one completed guard-result descriptor.
/// Output: contained boolean decision.
/// Transformation: unwraps the descriptor without crossing a runtime execution
/// boundary.

@pure
pub value(result: Completed): Bool.

/// GuardResult declares how a deferred guard result lifts a comprehension.
/// Input: result type `R` and unary lift container `F`.
/// Output: one `F[Bool]` decision consumed by the VM scheduler.
/// Transformation: makes effectful filtering an ordinary trait opt-in instead
/// of giving `Effect[Bool]` or any other container privileged syntax.

pub trait GuardResult[R, F[_]] {
    into_guard(result: R): F[Bool].
}.

pub impl GuardResult[std.core.Effect[Bool], std.core.Effect] for std.core.Effect[Bool] {
}.

//! Core integer conformance helpers.
//! `std.core.Int` provides named operations used by stdlib trait/conformance
//! implementations for primitive `Int`.

module std.core.Int.

/// Returns the absolute value of an `Int`.
/// Input: one `Int` value.
/// Output: the non-negative magnitude of the input.
/// Transformation: returns the input unchanged when it is non-negative;
/// otherwise subtracts it from zero.
/// ```terlan
/// module int_abs_example.
/// pub demo(): Int ->
///     std.core.Int.abs(-7).
/// ```

@pure
pub abs(value: Int): Int.

/// Compares two `Int` values using numeric total ordering.
/// Input: two `Int` values.
/// Output: `Lt` when `left` is numerically less than `right`, `Eq` when the
/// values are equal, and `Gt` when `left` is numerically greater than
/// `right`.
/// Transformation: maps the primitive integer ordering relation onto
/// `std.core.Ordering.Comparison`.
/// This function is the named implementation hook for compiler-known
/// `std.core.Ordering[Int]` conformance in 0.0.1.
/// ```terlan
/// module int_compare_example.
/// pub demo(): std.core.Ordering.Comparison ->
///    std.core.Int.compare(1, 2).
/// ```

@pure
pub compare(left: Int, right: Int): std.core.Ordering.Comparison.

/// Returns whether two `Int` values are equal.
/// Input: two `Int` values.
/// Output: `true` when both inputs represent the same integer; otherwise
/// `false`.
/// Transformation: delegates to exact Terlan equality for the primitive
/// integer domain without changing either input.
/// ```terlan
/// module int_equal_example.
/// pub demo(): Bool ->
///     std.core.Int.equal(42, 42).
/// ```

@pure
pub equal(left: Int, right: Int): Bool.

/// Parses a canonical UTF-8 `String` into `Int`.
/// Input: one `String` value.
/// Output: `Option[Int]`, where canonical signed decimal text returns
/// `Some(value)` and invalid text returns `None`.
/// Transformation: lowers through the compiler-owned `core.int.from_string`
/// intrinsic and accepts only inputs where the full string is consumed.
/// ```terlan
/// module int_from_string_example.
/// pub demo(): Option[Int] ->
///    std.core.Int.from_string("42").
/// ```

@pure
pub from_string(value: String): Option[Int].

/// Parses a complete signed integer string using a base from 2 through 36.
/// Input: canonical integer text and numeric base.
/// Output: `Some(Int)` when the full string is valid and in range, or `None`
/// for an invalid base, malformed text, or integer overflow.
/// Transformation: lowers through `core.int.from_string_base` and accepts both
/// uppercase and lowercase input digits.
/// ```terlan
/// module int_from_string_base_example.
/// pub demo(): Option[Int] ->
///     std.core.Int.from_string_base("FF", 16).
/// ```

@pure
pub from_string_base(value: String, base: Int): Option[Int].

/// Returns the larger of two `Int` values.
/// Input: two `Int` values.
/// Output: `left` when it is greater than or equal to `right`; otherwise
/// `right`.
/// Transformation: compares the two inputs with primitive integer ordering and
/// returns one original input unchanged.
/// ```terlan
/// module int_max_example.
/// pub demo(): Int ->
///     std.core.Int.max(7, 3).
/// ```

@pure
pub max(left: Int, right: Int): Int.

/// Returns the smaller of two `Int` values.
/// Input: two `Int` values.
/// Output: `left` when it is less than or equal to `right`; otherwise `right`.
/// Transformation: compares the two inputs with primitive integer ordering and
/// returns one original input unchanged.
/// ```terlan
/// module int_min_example.
/// pub demo(): Int ->
///     std.core.Int.min(3, 7).
/// ```

@pure
pub min(left: Int, right: Int): Int.

/// Renders an `Int` as its canonical UTF-8 `String`.
/// Input: one `Int` value.
/// Output: the canonical decimal string for the input integer.
/// Transformation: lowers through the compiler-owned `core.int.to_string`
/// intrinsic and returns the canonical text representation used by
/// `std.core.String.Show[Int]`.
/// ```terlan
/// module int_to_string_example.
/// pub demo(): String ->
///    std.core.Int.to_string(42).
/// ```

@pure
pub to_string(value: Int): String.

/// Renders an `Int` using an explicit base from 2 through 36.
/// Input: an integer value and numeric base.
/// Output: `Some(String)` with canonical uppercase digits, or `None` when the
/// base is outside the supported range.
/// Transformation: lowers through `core.int.to_string_base` without exposing
/// backend conversion functions or exceptions.
/// ```terlan
/// module int_to_string_base_example.
/// pub demo(): Option[String] ->
///     std.core.Int.to_string_base(255, 16).
/// ```

@pure
pub to_string_base(value: Int, base: Int): Option[String].

//! Target-aware memory introspection.
//! `std.core.Memory` exposes compiler-owned physical layout information and
//! runtime-owned managed-memory accounting without conflating either operation
//! with collection length or encoded payload size.

module std.core.Memory.

/// Values carried directly in native storage.

pub type Inline =
    Atom["Inline"].

/// Physical representation selected for one type on the current target.
/// `size` and `alignment` are expressed in bytes. They describe a value slot,
/// not the transitive memory retained by a managed value.

pub struct Layout {
    size: Int,
    alignment: Int,
    storage: Storage
}.

/// Actor-local references with runtime-accounted object payloads.

pub type Managed =
    Atom["Managed"].

/// Target resources without a portable inspectable representation.

pub type Opaque =
    Atom["Opaque"].

/// Storage class selected for a Terlan value representation.
/// `Inline` values are carried directly in native storage. `Managed` values are
/// actor-local references whose object payload is accounted for at runtime.
/// `Opaque` is reserved for target resources whose representation cannot be
/// inspected by portable code.

pub type Storage =
    Inline
  | Managed
  | Opaque.

/// Returns the current target's physical representation for `T`.
/// Input: one explicit type argument and no runtime value.
/// Output: size, alignment, and storage class for a value slot of `T`.
/// Transformation: lowers to a compiler-owned target-layout constant after
/// generic specialization.

pub layout_of[T](): Layout.

/// Returns distinct bytes transitively retained by one value.
/// Input: one value whose explicit type argument is `T`.
/// Output: direct scalar bytes or all distinct managed object and directly owned
/// payload bytes reachable from the value.
/// Transformation: folds scalar values to their target layout size and performs
/// cycle-safe, deduplicated traversal for managed values.

@pure
pub retained_size[T](value: T): Int.

/// Returns bytes owned directly by one value.
/// Input: one value whose explicit type argument is `T`.
/// Output: direct inline bytes or the fixed payload plus directly owned
/// out-of-line bytes of one managed object.
/// Transformation: folds scalar values to their target layout size and asks the
/// owning actor heap to measure managed values without traversing children.

@pure
pub shallow_size[T](value: T): Int.

//! Core dynamic object type.
//! `std.core.Object` represents language-neutral string-keyed dynamic data.
//! Structs remain fixed typed records; `Object[V]` is for JSON-like payloads,
//! configuration fragments, OpenAPI data, and other variable-key values.

module std.core.Object.

/// Object represents a dynamic string-keyed value map.
/// Input: one value type parameter `V`.
/// Output: an `Object[V]` whose keys are always portable UTF-8 `String` values.
/// Transformation: aliases the portable `Map[String, V]` contract so the VM can
/// use its owned map representation and native targets can lower to
/// deterministic map storage without introducing a separate target-specific
/// object model.

pub type Object[V] =
    std.collections.Map[String, V].

/// Removes every object member.
/// Input: a mutable `Object[V]` receiver.
/// Output: `Unit`.
/// Transformation: delegates to the map-backed `clear` receiver method.

pub (mut object: Object[V]) clear(): Unit.

/// Returns whether a key exists on an object.
/// Input: one `Object[V]` receiver and one `String` key.
/// Output: `true` when the key exists; otherwise `false`.
/// Transformation: delegates to the map-backed `contains_key` receiver method.

pub (object: Object[V]) contains_key(key: String): Bool.

/// Creates an object from explicit string-keyed entry tuples.
/// Input: one list of `{String, V}` entries.
/// Output: an `Object[V]` containing the supplied entries.
/// Transformation: delegates to `Map.from_entries` so duplicate-key handling and
/// backend representation remain identical to `Map[String, V]`.

pub from_entries[V](entries: List[{String, V}]): Object[V].

/// Looks up an object member by key.
/// Input: one `Object[V]` receiver and one `String` key.
/// Output: `Some(value)` when the member exists; otherwise `None`.
/// Transformation: delegates to the map-backed `get` receiver method.

pub (object: Object[V]) get(key: String): Option[V].

/// Returns whether an object contains no members.
/// Input: one `Object[V]`.
/// Output: `true` when the object has no members; otherwise `false`.
/// Transformation: delegates to the map-backed `is_empty` receiver method.

pub (object: Object[V]) is_empty(): Bool.

/// Creates an empty object.
/// Input: no value input.
/// Output: an empty `Object[V]`.
/// Transformation: delegates to `Map.new`, preserving the map-backed runtime
/// representation.

pub new[V](): Object[V].

/// Inserts or replaces an object member.
/// Input: a mutable `Object[V]` receiver, one `String` key, and one value.
/// Output: `Unit`.
/// Transformation: delegates to the map-backed `put` receiver method and keeps
/// Terlan mutable-receiver rebinding semantics.

pub (mut object: Object[V]) put(key: String, value: V): Unit.

/// Removes an object member if it exists.
/// Input: a mutable `Object[V]` receiver and one `String` key.
/// Output: `Unit`.
/// Transformation: delegates to the map-backed `remove` receiver method.

pub (mut object: Object[V]) remove(key: String): Unit.

/// Returns the number of object members.
/// Input: one `Object[V]`.
/// Output: the number of string-keyed members visible in the object.
/// Transformation: delegates to the map-backed `size` receiver method.

pub (object: Object[V]) size(): Int.

/// Constructs an object from explicit string-keyed entry tuples.
/// Input: zero or more `{String, V}` entries.
/// Output: an `Object[V]` containing the supplied entries.
/// Transformation: delegates to `std.collections.Map.from_entries`, preserving
/// the exact `Map[String, V]` runtime representation behind the `Object[V]`
/// source contract.

pub constructor Object[V] {
    (...entries: {String, V}): Object[V] ->
        Map.from_entries(entries)
}.

//! Core optional value type.
//! `std.core.Option` represents either no value or one present value.

module std.core.Option.

/// None represents a missing optional value.
/// `None` is a typed alias for the language-neutral atom primitive
/// `Atom["none"]`.
/// ```terlan
/// module none_type_example.
/// pub type None =
///    Atom["none"].
/// pub missing(): None ->
///    None.
/// ```

pub type None =
    Atom["none"].

/// Option represents an optional value.
/// Use `None` when no value is available and `Some(value)` when a value is
/// present.
/// ```terlan
/// module option_example.
/// pub type None =
///    Atom["none"].
/// pub type Some[T] =
///    {Atom["some"], value: T}.
/// pub type Option[T] =
///      None
///    | Some[T].
/// pub missing(): Option[Int] ->
///    None.
/// pub present(x: Int): Option[Int] ->
///    Some(x).
/// ```

pub type Option[T] =
    None
  | Some[T].

/// Some represents a present optional value.
/// `Some[T]` is a typed alias for the tuple `{Atom["some"], value}`.
/// ```terlan
/// module some_type_example.
/// pub type Some[T] =
///    {Atom["some"], value: T}.
/// pub present(value: Int): Some[Int] ->
///    Some(value).
/// ```

pub type Some[T] =
    {Atom["some"], value: T}.

/// Chains a present value into another optional computation.
/// `and_then` returns `None` when the input is missing. When the input is
/// present, it calls the supplied function and returns that function's
/// optional result directly.
/// ```terlan
/// module option_and_then_example.
/// pub type None = Atom["none"].
/// pub type Some[T] = {Atom["some"], value: T}.
/// pub type Option[T] =
///      None
///    | Some[T].
/// pub and_then(value: Option[A], f: (A) -> Option[B]): Option[B] ->
///    case value {
///        None ->
///            None;
///        Some(x) ->
///            f(x)
///    }.
/// pub demo(value: Option[Int], f: (Int) -> Option[Int]): Option[Int] ->
///    and_then(value, f).
/// ```

pub and_then(value: Option[A], f: (A) -> Option[B]): Option[B].

/// Compares two optional values using `None < Some(_)`.
/// Input: two `Option[A]` values and a comparator for present `A` values.
/// Output: `Lt` when `left` is ordered before `right`, `Eq` when they are
/// equal, and `Gt` when `left` is ordered after `right`.
/// Transformation: orders missing values before present values and delegates
/// present-value comparison to `value_compare`.
/// ```terlan
/// module option_compare_example.
/// import type std.core.Ordering.Comparison.
/// pub compare_int(left: Int, right: Int): Comparison ->
///    std.core.Int.compare(left, right).
/// pub demo(): Comparison ->
///    std.core.Option.compare(None, Some(1), compare_int).
/// ```

pub compare(left: Option[A], right: Option[A], value_compare: (A, A) -> std.core.Ordering.Comparison): std.core.Ordering.Comparison.

/// Returns whether an optional value is missing.
/// Input: one `Option[A]` value.
/// Output: `true` for `None` and `false` for `Some(value)`.
/// Transformation: inspects the option shape without changing the contained
/// value.
/// ```terlan
/// module option_is_none_example.
/// pub demo(value: Option[Int]): Bool ->
///    std.core.Option.is_none(value).
/// ```

@pure
pub is_none(value: Option[A]): Bool.

/// Returns whether an optional value is present.
/// Input: one `Option[A]` value.
/// Output: `true` for `Some(value)` and `false` for `None`.
/// Transformation: inspects the option shape without changing the contained
/// value.
/// ```terlan
/// module option_is_some_example.
/// pub demo(value: Option[Int]): Bool ->
///    std.core.Option.is_some(value).
/// ```

@pure
pub is_some(value: Option[A]): Bool.

/// Maps a present value and leaves `None` unchanged.
/// ```terlan
/// module option_map_example.
/// pub type None =
///    Atom["none"].
/// pub type Some[T] =
///    {Atom["some"], value: T}.
/// pub type Option[T] =
///      None
///    | Some[T].
/// pub map(value: Option[A], f: (A) -> B): Option[B] ->
///    case value {
///        None ->
///            None;
///        Some(x) ->
///            Some(f(x))
///    }.
/// pub demo(value: Option[Int], f: (Int) -> Int): Option[Int] ->
///    map(value, f).
/// ```

pub map(value: Option[A], f: (A) -> B): Option[B].

/// Extracts a present value or returns the provided default.
/// ```terlan
/// module option_with_default_example.
/// pub type None =
///    Atom["none"].
/// pub type Some[T] =
///    {Atom["some"], value: T}.
/// pub type Option[T] =
///      None
///    | Some[T].
/// pub with_default(value: Option[A], default: A): A ->
///    case value {
///        None ->
///            default;
///        Some(x) ->
///            x
///    }.
/// pub demo(value: Option[Int]): Int ->
///    with_default(value, 0).
/// ```

@pure
pub with_default(value: Option[A], default: A): A.

//! Core ordering trait and comparison result.
//! `std.core.Ordering` defines the trait for values that can be ordered. The
//! closed comparison result is named `Comparison`.

module std.core.Ordering.

/// Comparison is the closed result domain for total ordering.
/// ```terlan
/// module comparison_type_example.
/// pub choose(flag: Bool): Comparison ->
///    if {
///        flag -> Gt;
///        _ -> Lt
///    }.
/// ```

pub type Comparison =
    Lt
  | Eq
  | Gt.

/// Eq represents equal comparison.
/// ```terlan
/// module comparison_eq_example.
/// pub equal(): Eq ->
///    Eq.
/// ```

pub type Eq =
    Atom["eq"].

/// Gt represents greater-than comparison.
/// ```terlan
/// module comparison_gt_example.
/// pub greater(): Gt ->
///    Gt.
/// ```

pub type Gt =
    Atom["gt"].

/// Comparison represents less-than, equal, or greater-than comparison results.
/// Input: no runtime input; this is a closed result type.
/// Output: one of `Lt`, `Eq`, or `Gt`.
/// Transformation: gives ordering implementations a stable return domain
/// without making the `Ordering` trait itself a value.
/// ```terlan
/// module comparison_example.
/// pub type Comparison =
///      Lt
///    | Eq
///    | Gt.
/// pub less(): Comparison ->
///    Lt.
/// ```

pub type Lt =
    Atom["lt"].

/// Compares two `Comparison` values using declaration order.
/// Input: two `Comparison` values.
/// Output: `Lt` when `left` comes before `right`, `Eq` when both values are
/// equal, and `Gt` when `left` comes after `right`.
/// Transformation: orders the closed comparison result domain as
/// `Lt < Eq < Gt`.
/// This function is the named implementation hook for compiler-known
/// `std.core.Ordering[Comparison]` conformance in 0.0.1.
/// ```terlan
/// module comparison_compare_example.
/// pub demo(): Comparison ->
///    std.core.Ordering.compare(Lt, Gt).
/// ```

@pure
pub compare(left: Comparison, right: Comparison): Comparison.

/// Parses a canonical UTF-8 `String` into `Comparison`.
/// Input: one `String` value.
/// Output: `Option[Comparison]`, where `"lt"`, `"eq"`, and `"gt"` return their
/// corresponding comparison values and any other string returns `None`.
/// Transformation: recognizes only the canonical spellings used by
/// `std.core.String.Parse[Comparison]` and rejects all other strings.
/// ```terlan
/// module comparison_from_string_example.
/// pub demo(): Option[Comparison] ->
///    std.core.Ordering.from_string("lt").
/// ```

pub from_string(value: String): Option[Comparison].

