module mcp_query.

pub struct Base {
    code: Int
}.

pub struct Leaf {
    code: Int,
    label: String
}.

pub opaque type Secret.

pub shape Positive ( value ) = value where value > 0.

@pure
pub call_integer(): Int.

@pure
pub call_string(): String.

@pure
pub choose(value: Int): Int.

@pure
pub choose(value: String): String.

@pure
pub decide(flag: Bool): Bool.

@pure
pub display[T => {name: String}](value: T): String.

pub encode_bound[T]<Encode[T]>(value: T): String.

pub invoke_dynamic(callback: (Int) -> Int): Int.

@pure
pub positive(value: Int): Int.

pub trait Encode[T] {
    encode(value: T): String.
}.

pub impl not Encode[Secret].

pub impl Encode[Int] for Int {
}.
